package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Exact owned API67 source admitted by Salesforce deployment and all named tests.
func TestRunRSAKnownAnswers(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC1RsaProof.cls"), "@IsTest\nprivate class GladeC1RsaProof {\n    private static Blob message() { return Blob.valueOf('Glade owned RSA known answer 2026-09-05'); }\n    private static Blob privateKey() { return EncodingUtil.base64Decode(''); }\n    private static Blob publicKey() { return EncodingUtil.base64Decode(''); }\n    private static Blob wrongKey() { return EncodingUtil.base64Decode(''); }\n    private static Blob signature() { return EncodingUtil.base64Decode(''); }\n    @IsTest static void signMatchesIndependentVector() {\n        System.assertEquals(signature(), Crypto.sign('RSA-SHA256', message(), privateKey()));\n    }\n    @IsTest static void independentSignatureVerifies() {\n        System.assertEquals(true, Crypto.verify('RSA-SHA256', message(), signature(), publicKey()));\n    }\n    @IsTest static void wrongKeyRejects() {\n        System.assertEquals(false, Crypto.verify('RSA-SHA256', message(), signature(), wrongKey()));\n    }\n    @IsTest static void changedMessageRejects() {\n        System.assertEquals(false, Crypto.verify('RSA-SHA256', Blob.valueOf('changed'), signature(), publicKey()));\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC1RsaProof.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 4 || got.Passed != 4 {
		data, _ := json.Marshal(run)
		t.Fatalf("RSA cases failed: %s", data)
	}
}

// Exact owned API67 source admitted by Salesforce deployment and all named tests.
func TestRunRSAAdditionalAlgorithms(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC1RSAAlgorithms.cls"), "@IsTest private class GladeC1RSAAlgorithms {\n    private static Blob message() { return Blob.valueOf('Glade owned RSA known answer 2026-09-05'); }\n    private static Blob privateKey() { return EncodingUtil.base64Decode(''); }\n    private static Blob publicKey() { return EncodingUtil.base64Decode(''); }\n    @IsTest static void signRSA() {\n        System.assertEquals('', EncodingUtil.base64Encode(Crypto.sign('RSA', message(), privateKey())));\n    }\n    @IsTest static void verifyRSA() {\n        System.assertEquals(true, Crypto.verify('RSA', message(), EncodingUtil.base64Decode(''), publicKey()));\n    }\n    @IsTest static void signRSASHA1() {\n        System.assertEquals('', EncodingUtil.base64Encode(Crypto.sign('RSA-SHA1', message(), privateKey())));\n    }\n    @IsTest static void verifyRSASHA1() {\n        System.assertEquals(true, Crypto.verify('RSA-SHA1', message(), EncodingUtil.base64Decode(''), publicKey()));\n    }\n    @IsTest static void signRSASHA384() {\n        System.assertEquals('', EncodingUtil.base64Encode(Crypto.sign('RSA-SHA384', message(), privateKey())));\n    }\n    @IsTest static void verifyRSASHA384() {\n        System.assertEquals(true, Crypto.verify('RSA-SHA384', message(), EncodingUtil.base64Decode(''), publicKey()));\n    }\n    @IsTest static void signRSASHA512() {\n        System.assertEquals('', EncodingUtil.base64Encode(Crypto.sign('RSA-SHA512', message(), privateKey())));\n    }\n    @IsTest static void verifyRSASHA512() {\n        System.assertEquals(true, Crypto.verify('RSA-SHA512', message(), EncodingUtil.base64Decode(''), publicKey()));\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC1RSAAlgorithms.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 8 || got.Passed != 8 {
		data, _ := json.Marshal(run)
		t.Fatalf("RSA cases failed: %s", data)
	}
}

// Exact owned API67 source admitted by Salesforce deployment and all named tests.
func TestRunRSAInvalidKeys(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC1RSAInvalidKey.cls"), "@IsTest private class GladeC1RSAInvalidKey {\n    @IsTest static void signMalformedPrivateKeyThrowsSecurityException() {\n        Boolean caught = false;\n        try {\n            Crypto.sign('RSA-SHA256', Blob.valueOf('Glade malformed key observation'), Blob.valueOf('not a DER private key'));\n        } catch (SecurityException problem) {\n            caught = true;\n            System.assertEquals('Invalid Crypto Key', problem.getMessage());\n        }\n        System.assertEquals(true, caught, 'Expected SecurityException for malformed key');\n    }\n    @IsTest static void verifyMalformedPublicKeyThrowsSecurityException() {\n        Boolean caught = false;\n        try {\n            Crypto.verify('RSA-SHA256', Blob.valueOf('Glade owned RSA known answer 2026-09-05'), EncodingUtil.base64Decode(''), Blob.valueOf('not a DER public key'));\n        } catch (SecurityException problem) {\n            caught = true;\n            System.assertEquals('Invalid Crypto Key', problem.getMessage());\n        }\n        System.assertEquals(true, caught, 'Expected SecurityException for malformed key');\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeC1RSAInvalidKey.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 2 || got.Passed != 2 {
		data, _ := json.Marshal(run)
		t.Fatalf("RSA cases failed: %s", data)
	}
}
